// Gross properties of a welded (doubly-unsymmetric) I-section.
// Port of the "Gross section properties" block of ltb_moment_capacity_welded().
// Dimensions in mm; y_bar / y_pna are measured from the BOTTOM of the bottom flange.
const bf_top = Number(inputs["bf_top"]) || 0;
const tf_top = Number(inputs["tf_top"]) || 0;
const bf_bot = Number(inputs["bf_bot"]) || 0;
const tf_bot = Number(inputs["tf_bot"]) || 0;
const d_web  = Number(inputs["d_web"])  || 0;   // clear web depth between flanges
const tw     = Number(inputs["tw"])     || 0;

const A_top = bf_top * tf_top;
const A_bot = bf_bot * tf_bot;
const A_web = d_web * tw;
const A_total = A_top + A_bot + A_web;

const y_bot_flange_centroid = tf_bot / 2;
const y_web_centroid = tf_bot + d_web / 2;
const y_top_flange_centroid = tf_bot + d_web + tf_top / 2;

const y_bar = (A_bot * y_bot_flange_centroid + A_web * y_web_centroid + A_top * y_top_flange_centroid) / A_total;

const overall_depth = tf_bot + d_web + tf_top;
const y_top_extreme = overall_depth - y_bar;

const I_bot = (bf_bot * Math.pow(tf_bot, 3) / 12) + A_bot * ((y_bar - y_bot_flange_centroid) * (y_bar - y_bot_flange_centroid));
const I_web = (tw * Math.pow(d_web, 3) / 12) + A_web * ((y_bar - y_web_centroid) * (y_bar - y_web_centroid));
const I_top = (bf_top * Math.pow(tf_top, 3) / 12) + A_top * ((y_bar - y_top_flange_centroid) * (y_bar - y_top_flange_centroid));
const I_z_gross = I_bot + I_web + I_top;

const I_y_gross = (tf_top * Math.pow(bf_top, 3) / 12) + (tf_bot * Math.pow(bf_bot, 3) / 12) + (d_web * Math.pow(tw, 3) / 12);

const Z_e_gross = I_z_gross / y_top_extreme;      // elastic modulus, extreme TOP fibre

// Plastic modulus — the original's two-branch equal-area-axis search, verbatim:
//   branch 1  equal-area axis lies inside the BOTTOM flange
//   branch 2  equal-area axis lies inside the WEB
// There is deliberately no third branch, so a section whose axis would fall in
// the TOP flange is extrapolated rather than solved (kept as in the original).
const half_area = A_total / 2.0;
let y_pna = 0.0;
let Z_p = 0.0;
if (A_bot >= half_area) {
  y_pna = half_area / bf_bot;
  Z_p += bf_bot * (y_pna * y_pna) / 2.0;
  Z_p += bf_bot * ((tf_bot - y_pna) * (tf_bot - y_pna)) / 2.0;
  Z_p += A_web * (tf_bot - y_pna + d_web / 2);
  Z_p += A_top * (tf_bot - y_pna + d_web + tf_top / 2);
} else {
  const remaining = half_area - A_bot;
  const y_web_comp = remaining / tw;
  y_pna = tf_bot + y_web_comp;
  Z_p += A_bot * (y_pna - y_bot_flange_centroid);
  Z_p += tw * (y_web_comp * y_web_comp) / 2.0;
  const y_web_tens_centroid = tf_bot + y_web_comp + (d_web - y_web_comp) / 2;
  Z_p += (tw * (d_web - y_web_comp)) * (y_web_tens_centroid - y_pna);
  Z_p += A_top * (y_top_flange_centroid - y_pna);
}

// flange-centroid distance used by the M_cr formula
const h_f = overall_depth - tf_top / 2 - tf_bot / 2;

return { "overall_depth": overall_depth, "h_f": h_f, "A_total": A_total, "y_bar": y_bar, "y_pna": y_pna, "I_z_gross": I_z_gross, "I_y_gross": I_y_gross, "Z_e_gross": Z_e_gross, "Z_p": Z_p };

// Section classification per IRC:24-2010 / IS 800:2007 — port of
// classify_section_irc24(). Only the compression (top) flange and the web are
// classified; the bottom tension flange ratio is reported for information.
// section_type must be exactly "welded" — any other string uses the ROLLED
// outstand limits (same case-sensitive test as the original).
const bf_top = Number(inputs["bf_top"]) || 0;
const tf_top = Number(inputs["tf_top"]) || 0;
const bf_bot = Number(inputs["bf_bot"]) || 0;
const tf_bot = Number(inputs["tf_bot"]) || 0;
const d_web  = Number(inputs["d_web"])  || 0;
const tw     = Number(inputs["tw"])     || 0;
const fy     = Number(inputs["fy"])     || 0;
const section_type = String(inputs["section_type"]);

const epsilon = Math.sqrt(250 / fy);              // NOTE: 250 here (classification)
const welded = section_type === "welded";

// top (compression) flange outstand ratio
const b_tf_top = welded ? (bf_top - tw) / 2 / tf_top : bf_top / 2 / tf_top;

// web slenderness (internal element in bending)
const d_tw = d_web / tw;

const plastic_limit_flange    = (welded ?  8.4 :  9.4) * epsilon;
const compact_limit_flange    = (welded ?  9.4 : 10.5) * epsilon;
const semi_compact_limit_flange = (welded ? 13.6 : 15.7) * epsilon;

const plastic_limit_web    =  84 * epsilon;
const compact_limit_web    = 105 * epsilon;
const semi_compact_limit_web = 126 * epsilon;

const top_flange_class = b_tf_top <= plastic_limit_flange ? "Plastic"
  : b_tf_top <= compact_limit_flange ? "Compact"
  : b_tf_top <= semi_compact_limit_flange ? "Semi-compact"
  : "Slender";

const web_class = d_tw <= plastic_limit_web ? "Plastic"
  : d_tw <= compact_limit_web ? "Compact"
  : d_tw <= semi_compact_limit_web ? "Semi-compact"
  : "Slender";

// overall class = the more critical of top flange and web (ties -> top flange,
// matching Python's max([top, web], key=rank))
const RANK = { "Plastic": 1, "Compact": 2, "Semi-compact": 3, "Slender": 4 };
const overall_class = RANK[top_flange_class] >= RANK[web_class] ? top_flange_class : web_class;

// bottom flange b/t ratio, information only
const b_tf_bot = welded ? (bf_bot - tw) / 2 / tf_bot : bf_bot / 2 / tf_bot;

return {
  "epsilon": epsilon,
  "b_tf_top": b_tf_top,
  "top_flange_class": top_flange_class,
  "top_plastic_limit": plastic_limit_flange,
  "top_compact_limit": compact_limit_flange,
  "top_semi_compact_limit": semi_compact_limit_flange,
  "b_tf_bot": b_tf_bot,
  "d_tw": d_tw,
  "web_class": web_class,
  "web_plastic_limit": plastic_limit_web,
  "web_compact_limit": compact_limit_web,
  "web_semi_compact_limit": semi_compact_limit_web,
  "overall_class": overall_class,
  "top_flange_slender": top_flange_class === "Slender",
  "web_slender": web_class === "Slender",
};

// Effective (post local-buckling) section properties — port of
// calculate_effective_section_properties() with effective_width_outstand() and
// effective_depth_web_comp() inlined (both are called with the original's
// default stress ratio psi = 1.0).
// NOTE (verbatim from the original): the plate slenderness here uses
// eps = sqrt(235/fy) — EC3 — while CLASSIFICATION uses sqrt(250/fy); and the
// lambda_p denominators omit the EN 1993-1-5 Table 4.2 sqrt(k_sigma) factor
// (0.43 for an outstand, 4.0 for an internal web), which makes rho smaller,
// i.e. more conservative. Both quirks are preserved on purpose.
const bf_top = Number(inputs["bf_top"]) || 0;
const tf_top = Number(inputs["tf_top"]) || 0;
const bf_bot = Number(inputs["bf_bot"]) || 0;
const tf_bot = Number(inputs["tf_bot"]) || 0;
const d_web  = Number(inputs["d_web"])  || 0;
const tw     = Number(inputs["tw"])     || 0;
const fy     = Number(inputs["fy"])     || 0;
const top_slender = Boolean(inputs["top_slender"]);
const web_slender = Boolean(inputs["web_slender"]);

const psi = 1.0;                                  // stress ratio, original default
const epsilon = Math.sqrt(235 / fy);              // NOTE: 235 here, 250 in classification

// ── outstand compression flange: rho * b ──
// The effective section always assumes the WELDED outstand (bf_top - tw)/2,
// exactly as the original does.
const outstand = (bf_top - tw) / 2;
const lambda_p_flange = (outstand / tf_top) / (28.4 * epsilon * Math.sqrt(psi));
const rho_flange = lambda_p_flange <= 0.748 ? 1.0
  : Math.min((lambda_p_flange - 0.188) / (lambda_p_flange * lambda_p_flange), 1.0);

let b_eff_top = bf_top;
const b_eff_bot = bf_bot;                          // tension flange: never reduced
if (top_slender) b_eff_top = 2 * (rho_flange * outstand) + tw;

// ── neutral axis of the partially effective section (flange reduced, web full) ──
const A_top_p = b_eff_top * tf_top;
const A_bot_p = b_eff_bot * tf_bot;
const A_web_p = d_web * tw;
const A_total_p = A_top_p + A_bot_p + A_web_p;
const y_bar_p = (A_bot_p * (tf_bot / 2) + A_web_p * (tf_bot + d_web / 2) + A_top_p * (tf_bot + d_web + tf_top / 2)) / A_total_p;
const overall_depth = tf_bot + d_web + tf_top;
const d_comp = overall_depth - y_bar_p - tf_top;    // web depth in compression

// ── slender web: rho * d_comp for the compression part, tension part kept whole ──
const lambda_p_web = (d_comp / tw) / (28.4 * epsilon * Math.sqrt(psi));
const rho_web = lambda_p_web <= 0.673 ? 1.0
  : Math.min((lambda_p_web - 0.055 * (3 + psi)) / (lambda_p_web * lambda_p_web), 1.0);

let d_web_eff = d_web;
if (web_slender) {
  const d_comp_eff = rho_web * d_comp;
  const d_tension = d_web - d_comp;
  d_web_eff = d_comp_eff + d_tension;
}

// ── recompute the section with the effective dimensions ──
const A_top = b_eff_top * tf_top;
const A_bot = b_eff_bot * tf_bot;
const A_web = d_web_eff * tw;
const A_eff = A_top + A_bot + A_web;

const y_bot_flange_centroid = tf_bot / 2;
const y_web_centroid = tf_bot + d_web_eff / 2;
const y_top_flange_centroid = tf_bot + d_web_eff + tf_top / 2;

const y_bar_eff = (A_bot * y_bot_flange_centroid + A_web * y_web_centroid + A_top * y_top_flange_centroid) / A_eff;

const overall_depth_eff = tf_bot + d_web_eff + tf_top;
const y_top_extreme = overall_depth_eff - y_bar_eff;

const I_bot = (b_eff_bot * Math.pow(tf_bot, 3) / 12) + A_bot * ((y_bar_eff - y_bot_flange_centroid) * (y_bar_eff - y_bot_flange_centroid));
const I_web = (tw * Math.pow(d_web_eff, 3) / 12) + A_web * ((y_bar_eff - y_web_centroid) * (y_bar_eff - y_web_centroid));
const I_top = (b_eff_top * Math.pow(tf_top, 3) / 12) + A_top * ((y_bar_eff - y_top_flange_centroid) * (y_bar_eff - y_top_flange_centroid));
const I_z_eff = I_bot + I_web + I_top;

const Z_e_eff = I_z_eff / y_top_extreme;

return { "b_eff_top": b_eff_top, "b_eff_bot": b_eff_bot, "d_web_eff": d_web_eff, "A_eff": A_eff, "y_bar_eff": y_bar_eff, "I_z_eff": I_z_eff, "Z_e_eff": Z_e_eff, "d_comp": d_comp, "epsilon_235": epsilon, "lambda_p_flange": lambda_p_flange, "rho_flange": rho_flange, "lambda_p_web": lambda_p_web, "rho_web": rho_web };

// Design flexural capacity with lateral-torsional buckling — port of
// ltb_moment_capacity_welded() from the classification step onwards
// (the gross properties come from the "Gross I-Section Props" node, r_y from
// the built-in Radius of Gyration node, Z_e_eff from the effective-section node).
// Units: mm / MPa / N-mm in, kNm out.
const I_y_gross = Number(inputs["I_y_gross"]) || 0;
const h_f       = Number(inputs["h_f"])       || 0;   // flange centroid distance
const tf_top    = Number(inputs["tf_top"])    || 0;   // t_f in the M_cr formula
const r_y       = Number(inputs["r_y"])       || 0;
const Z_e_gross = Number(inputs["Z_e_gross"]) || 0;
const Z_p       = Number(inputs["Z_p"])       || 0;
const Z_e_eff   = Number(inputs["Z_e_eff"])   || 0;
const L_lt      = Number(inputs["L_lt"])      || 0;   // mm, unbraced length
const fy        = Number(inputs["fy"])        || 0;
const gamma_m0  = Number(inputs["gamma_m0"])  || 1.10;
const curve     = String(inputs["curve"]);            // 'c' or 'd'
const overall_class = String(inputs["overall_class"]);
const override_raw  = String(inputs["class_override"]).trim();

const E = 2e5;                                  // MPa, hardcoded in the original

// ── section class ──  "auto" / "" / "none" reproduces section_class=None
const is_auto = override_raw === "" || override_raw.toLowerCase() === "auto" || override_raw.toLowerCase() === "none";
const section_class = is_auto ? overall_class : override_raw;
const cls = section_class.toLowerCase();
const slender = cls === "slender";
const plast_compact = cls === "plastic" || cls === "compact";

// ── Z_used and beta_b ──
let Z_used = 0.0;
let beta_b = 1.0;
if (slender) { Z_used = Z_e_eff; beta_b = 1.0; }
else {
  Z_used = plast_compact ? Z_p : Z_e_gross;
  beta_b = plast_compact ? 1.0 : Z_e_gross / Z_p;
}

// ── elastic critical LTB moment (IS 800 / IRC:24 formula) ──
const term1 = (Math.PI * Math.PI * E * I_y_gross * h_f) / (2 * L_lt * L_lt);
const mcr_ratio = (L_lt / r_y) / (h_f / tf_top);
const mcr_factor = Math.sqrt(1 + (1 / 20) * (mcr_ratio * mcr_ratio));
const M_cr = term1 * mcr_factor;                // N-mm
const M_cr_kNm = M_cr / 1e6;

// ── non-dimensional slenderness lambda_LT ──
const M_eff_Nmm = slender ? Z_e_eff * fy : (plast_compact ? beta_b * Z_p * fy : Z_e_gross * fy);
const lambda_LT = Math.sqrt(M_eff_Nmm / M_cr);

// ── reduction factor chi_LT (buckling curve c or d) ──
let chi_LT = 1.0;
let phi_LT = 0.0;
let alpha_LT = 0.0;                             // None in the original when LTB does not govern
const ltb_governs = lambda_LT > 0.4;
if (lambda_LT > 0.4) {
  if (curve === "c") alpha_LT = 0.49;
  else if (curve === "d") alpha_LT = 0.76;
  else throw new Error("curve must be 'c' or 'd' (got '" + curve + "')");
  phi_LT = 0.5 * (1 + alpha_LT * (lambda_LT - 0.2) + lambda_LT * lambda_LT);
  chi_LT = 1.0 / (phi_LT + Math.sqrt(phi_LT * phi_LT - lambda_LT * lambda_LT));
  chi_LT = Math.min(chi_LT, 1.0);
}

// ── design bending stress and moments ──
const f_bd = chi_LT * fy / gamma_m0;
const M_d = slender ? Z_e_eff * f_bd : beta_b * Z_p * f_bd;
const M_d_kNm = M_d / 1e6;

const M_d_no_ltb = slender ? Z_e_eff * fy / gamma_m0 : beta_b * Z_p * fy / gamma_m0;
const M_d_no_ltb_kNm = M_d_no_ltb / 1e6;

const alpha_str = ltb_governs ? String(alpha_LT) + "  (curve " + curve + ")" : "n/a  (λ_LT ≤ 0.4)";
const Status = (ltb_governs
  ? "LTB governs — λ_LT = " + lambda_LT.toFixed(4) + " > 0.4, χ_LT = " + chi_LT.toFixed(4)
  : "LTB does not govern — λ_LT = " + lambda_LT.toFixed(4) + " ≤ 0.4, χ_LT = 1.0")
  + "  |  class: " + section_class;

return { "section_class": section_class, "beta_b": beta_b, "Z_used": Z_used, "term1": term1, "mcr_ratio": mcr_ratio, "mcr_factor": mcr_factor, "M_cr_kNm": M_cr_kNm, "M_eff_Nmm": M_eff_Nmm, "lambda_LT": lambda_LT, "phi_LT": phi_LT, "chi_LT": chi_LT, "alpha_LT": alpha_LT, "alpha_str": alpha_str, "f_bd": f_bd, "M_d_kNm": M_d_kNm, "M_d_no_ltb_kNm": M_d_no_ltb_kNm, "ltb_governs": ltb_governs, "Status": Status };
